class CBTInserter {
  private final java.util.Queue<TreeNode> q = new java.util.ArrayDeque<>();
  private TreeNode root;

  public CBTInserter(TreeNode root) {
    this.root = root;
    java.util.Queue<TreeNode> all = new java.util.ArrayDeque<>();
    all.add(root);
    while (!all.isEmpty()) {
      TreeNode n = all.poll();
      if (n.left == null || n.right == null) q.add(n);
      if (n.left != null) all.add(n.left);
      if (n.right != null) all.add(n.right);
    }
  }

  public int insert(int val) {
    TreeNode p = q.peek(), n = new TreeNode(val);
    if (p.left == null) p.left = n;
    else {
      p.right = n;
      q.poll();
    }
    q.add(n);
    return p.val;
  }

  public TreeNode get_root() {
    return root;
  }
}
